package main

import (
	"bytes"
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/aperturerobotics/protobuf-go-lite/types/descriptorpb"
)

// pythonLibrary is the handwritten part of the Python library, which the
// generated module ends with.
const pythonLibrary = "python/library.py"

// pythonPreamble opens the generated module with its imports, the vector
// types and the call every generated function makes.
const pythonPreamble = `# Code generated by modlock-sdkgen from the schema and python/library.py.
# DO NOT EDIT.

import dataclasses
import enum
import traceback
from collections.abc import Callable, Mapping
from typing import Any, Literal

import _modlock

from . import wire


@dataclasses.dataclass(slots=True)
class Vector:
    """Vector is a position or direction in the world, in game units."""

    x: float = 0.0
    y: float = 0.0
    z: float = 0.0


@dataclasses.dataclass(slots=True)
class Angles:
    """Angles is a rotation in degrees."""

    pitch: float = 0.0
    yaw: float = 0.0
    roll: float = 0.0


def _call(method: str, request_type: str, request: Any, response_type: str | None = None) -> Any:
    """_call calls one Host method with its request and returns the decoded
    response, True when the method answers nothing, or None when the call
    failed; the host logs why."""
    encoded = wire.encode(_SCHEMA, "Call", {"method": method, "request": wire.encode(_SCHEMA, request_type, request)})
    reply = wire.decode(_SCHEMA, "Reply", _modlock.call(encoded))
    if reply["error"]:
        return None
    if response_type is None:
        return True
    return wire.decode(_SCHEMA, response_type, reply["response"])


def _with(options: Any, name: str, value: Any) -> dict[str, Any]:
    """_with returns the fields of options with value under name."""
    request = {f.name: getattr(options, f.name) for f in dataclasses.fields(options)}
    request[name] = value
    return request


`

// pythonWriter writes the Python library's module.
type pythonWriter struct {
	*directions
	s     *schema
	out   bytes.Buffer
	calls []*call
	// absent holds the result field of each call that answers None when the
	// host leaves it out.
	absent map[*field]bool
}

// writePython returns python/modlock/__init__.py, which ends with the
// handwritten python/library.py.
func writePython(s *schema) ([]byte, error) {
	calls, err := s.calls()
	if err != nil {
		return nil, err
	}
	library, err := os.ReadFile(pythonLibrary)
	if err != nil {
		return nil, err
	}
	w := &pythonWriter{directions: s.directions(calls), s: s, calls: calls, absent: map[*field]bool{}}
	for _, c := range calls {
		if f := c.result; f != nil && f.message != nil && !f.repeated && !f.message.isBareUnion() {
			w.absent[f] = true
		}
	}
	w.out.WriteString(pythonPreamble)
	w.writeTypes()
	for _, c := range classes {
		w.writeClass(c)
	}
	if err := w.writeSchema(); err != nil {
		return nil, err
	}
	for _, c := range calls {
		if c.class == nil {
			w.writeCall(c, "")
			w.out.WriteString("\n\n")
		}
	}
	w.writeMod()
	w.out.Write(library)
	return w.out.Bytes(), nil
}

// hasClass reports whether m is a dataclass of the library. The messages
// only the library itself encodes or decodes are dicts.
func (w *pythonWriter) hasClass(m *message) bool {
	return mapped(m) == "" && !m.isBareUnion() && (w.inputs[m] || w.outputs[m])
}

// writeTypes writes the enums, with their tables, and the message types in
// schema order.
func (w *pythonWriter) writeTypes() {
	for _, e := range w.s.enumOrder {
		if !w.enumsIn[e] && !w.enumsOut[e] {
			continue
		}
		writeComment(&w.out, "", "#", e.doc)
		var names, entries []string
		for _, v := range e.named() {
			name := pythonValue(e, v)
			names = append(names, fmt.Sprintf("%q", name))
			entries = append(entries, fmt.Sprintf("    %d: %q,\n    %q: %d,\n", v.number, name, name, v.number))
		}
		line := fmt.Sprintf("type %s = Literal[%s]\n", e.name, strings.Join(names, ", "))
		if len(line) > 120 {
			line = fmt.Sprintf("type %s = Literal[\n    %s,\n]\n", e.name, strings.Join(names, ",\n    "))
		}
		w.out.WriteString(line)
		fmt.Fprintf(&w.out, "_%s: dict[Any, Any] = {\n%s}\n\n\n", e.name, strings.Join(entries, ""))
	}
	for _, m := range w.s.messageOrder {
		if mapped(m) != "" || (!w.inputs[m] && !w.outputs[m]) {
			continue
		}
		if m.isBareUnion() {
			writeComment(&w.out, "", "#", m.doc)
			fmt.Fprintf(&w.out, "type %s = %s\n\n\n", m.name, w.oneofType(m.oneofs[0]))
			continue
		}
		fmt.Fprintf(&w.out, "@dataclasses.dataclass(slots=True, kw_only=True)\nclass %s:\n", m.name)
		writePythonDocstring(&w.out, "    ", m.doc)
		switch {
		case m.doc == "" && len(m.fields) == 0:
			w.out.WriteString("    pass\n")
		case m.doc != "" && len(m.fields) > 0:
			w.out.WriteString("\n")
		}
		for _, f := range m.fields {
			if f == w.omitted[m] {
				continue
			}
			if o := f.oneof; o != nil && !o.keyed {
				if o.fields[0] == f {
					writeComment(&w.out, "    ", "#", pythonFieldDoc(m, rename(o.doc, camel(o.name), o.name)))
					fmt.Fprintf(&w.out, "    %s: %s | None = None\n", pythonName(o.name), w.oneofType(o))
				}
				continue
			}
			writeComment(&w.out, "    ", "#", pythonFieldDoc(m, f.doc))
			fmt.Fprintf(&w.out, "    %s: %s\n", pythonName(f.name), w.member(m, f))
		}
		w.out.WriteString("\n\n")
	}
}

// member returns the annotation and default of field f of message m. A mod
// leaves out a member with a default; the rest it writes.
func (w *pythonWriter) member(m *message, f *field) string {
	t := pythonType(f)
	switch {
	case f.repeated:
		return t + " = dataclasses.field(default_factory=lambda: " + t + "())"
	case f.optional, f.oneof != nil, f.enum != nil && w.outputs[m], f.message != nil && f.message.isBareUnion():
		return t + " | None = None"
	case f.message != nil, f.enum != nil, classOf(f) != nil:
		return t
	}
	return t + " = " + pythonZero(f)
}

// oneofType returns the union of the types of o's cases. The encoder finds
// the case of a value by its type, taking the first case that matches, so a
// later case of the same Python type only decodes.
func (w *pythonWriter) oneofType(o *oneof) string {
	seen := map[string]bool{}
	var types []string
	for _, f := range o.fields {
		if t := pythonBase(f); !seen[t] {
			seen[t] = true
			types = append(types, t)
		}
	}
	return strings.Join(types, " | ")
}

// writeClass writes one class: a frozen dataclass of its key, with its calls
// as methods.
func (w *pythonWriter) writeClass(c *class) {
	fmt.Fprintf(&w.out, "@dataclasses.dataclass(frozen=True, slots=True)\nclass %s:\n", c.name)
	writePythonDocstring(&w.out, "    ", c.doc)
	if c.doc != "" {
		w.out.WriteString("\n")
	}
	writeComment(&w.out, "    ", "#", c.keyDoc)
	fmt.Fprintf(&w.out, "    %s: int\n", c.key)
	for _, call := range w.calls {
		if call.class == c {
			w.out.WriteString("\n")
			w.writeCall(call, "    ")
		}
	}
	w.out.WriteString("\n\n")
}

// params returns the declared parameters of c, without its receiver.
func (w *pythonWriter) params(c *call) []string {
	if c.options {
		return []string{"options: " + c.method.request.name}
	}
	var params []string
	for _, p := range c.params {
		var t string
		if p.oneof != nil {
			t = w.oneofType(p.oneof)
		} else {
			t = pythonType(p.field)
		}
		if p.optional {
			t += " | None = None"
		}
		params = append(params, fmt.Sprintf("%s: %s", pythonName(p.paramName()), t))
	}
	return params
}

// resultType returns the type a call returns and the value it returns when
// the call fails.
func (w *pythonWriter) resultType(c *call) (string, string) {
	f := c.result
	switch {
	case f == nil:
		return "bool", "False"
	case f.repeated:
		return pythonType(f), "[]"
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_BOOL && !f.optional:
		return "bool", "False"
	}
	return pythonBase(f) + " | None", "None"
}

// writeCall writes one call as a method of its class at indent, or else as a
// function of the module.
func (w *pythonWriter) writeCall(c *call, indent string) {
	params := w.params(c)
	if c.class != nil {
		params = append([]string{"self"}, params...)
	}
	result, failure := w.resultType(c)
	fmt.Fprintf(&w.out, "%sdef %s(%s) -> %s:\n", indent, pythonName(snake(c.name)), strings.Join(params, ", "), result)
	writePythonDocstring(&w.out, indent+"    ", rename(c.method.doc, c.method.name, snake(c.name)))

	// Build the request.
	var request string
	switch {
	case c.options && c.receiver != nil:
		request = fmt.Sprintf("_with(options, %q, self)", c.receiver.name)
	case c.options:
		request = "options"
	default:
		var members []string
		if c.receiver != nil {
			members = append(members, fmt.Sprintf("%q: self", c.receiver.name))
		}
		for _, p := range c.params {
			members = append(members, fmt.Sprintf("%q: %s", pythonName(p.paramName()), pythonName(p.paramName())))
		}
		request = "{" + strings.Join(members, ", ") + "}"
	}
	send := fmt.Sprintf("_call(%q, %q, %s", c.method.name, c.method.request.name, request)
	if c.result == nil {
		fmt.Fprintf(&w.out, "%s    return %s) is not None\n", indent, send)
		return
	}
	fmt.Fprintf(&w.out, "%s    response = %s, %q)\n", indent, send, c.method.response.name)
	fmt.Fprintf(&w.out, "%s    if response is None:\n%s        return %s\n", indent, indent, failure)
	fmt.Fprintf(&w.out, "%s    return response[%q]\n", indent, pythonName(c.result.name))
}

// writeSchema writes the descriptor of every message the library encodes or
// decodes.
func (w *pythonWriter) writeSchema() error {
	var r reach
	for _, m := range w.s.messageOrder {
		if m.name == "Call" || m.name == "Reply" || m.name == "Empty" {
			r.add(m)
		}
	}
	for _, c := range w.calls {
		r.add(c.method.request)
		r.add(c.method.response)
	}
	for _, m := range w.s.mod.methods {
		r.add(m.request)
		r.add(m.response)
	}
	w.out.WriteString("# _SCHEMA describes every message the library encodes or decodes.\n")
	w.out.WriteString("_SCHEMA: wire.Schema = {\n")
	for _, m := range w.s.messageOrder {
		if !r.seen[m] {
			continue
		}
		cls := "None"
		switch {
		case mapped(m) != "":
			cls = mapped(m)
		case w.hasClass(m):
			cls = m.name
		}
		if len(m.fields) == 0 {
			fmt.Fprintf(&w.out, "    %q: (%s, []),\n", m.name, cls)
			continue
		}
		fmt.Fprintf(&w.out, "    %q: (\n        %s,\n        [\n", m.name, cls)
		for _, f := range m.fields {
			descriptor, err := w.descriptor(f)
			if err != nil {
				return fmt.Errorf("%s: %w", m.name, err)
			}
			fmt.Fprintf(&w.out, "            wire.Field(%s),\n", descriptor)
		}
		w.out.WriteString("        ],\n    ),\n")
	}
	w.out.WriteString("}\n\n\n")
	return nil
}

// descriptor returns the arguments of f's descriptor.
func (w *pythonWriter) descriptor(f *field) (string, error) {
	kind, ok := luauKinds[f.kind]
	if !ok {
		return "", fmt.Errorf("the Python codec has no %s for %s", f.kind, f.name)
	}
	args := []string{fmt.Sprintf("%d", f.number), fmt.Sprintf("%q", pythonName(f.name)), fmt.Sprintf("%q", kind)}
	switch {
	case f.repeated:
		args = append(args, "repeated=True")
	case f.optional || w.absent[f] || f.oneof != nil && f.oneof.keyed:
		args = append(args, "optional=True")
	}
	if f.oneof != nil && !f.oneof.keyed {
		args = append(args, fmt.Sprintf("oneof=%q", pythonName(f.oneof.name)))
	}
	if f.message != nil {
		args = append(args, fmt.Sprintf("message=%q", f.message.name))
		if f.message.isBareUnion() {
			args = append(args, fmt.Sprintf("union=%q", pythonName(f.message.oneofs[0].name)))
		}
	}
	if f.enum != nil {
		args = append(args, "enum=_"+f.enum.name)
	}
	if c := classOf(f); c != nil {
		args = append(args, "cls="+c.name, fmt.Sprintf("key=%q", c.key))
	}
	return strings.Join(args, ", "), nil
}

// writeMod writes the table of the mod's events and the dispatch that runs
// their handlers.
func (w *pythonWriter) writeMod() {
	w.out.WriteString("# _EVENTS holds each Mod method's request, response and handler.\n")
	w.out.WriteString("_EVENTS: dict[str, tuple[str, str, str]] = {\n")
	for _, m := range w.s.mod.methods {
		fmt.Fprintf(&w.out, "    %q: (%q, %q, %q),\n", m.name, m.request.name, m.response.name, snake(m.name))
	}
	w.out.WriteString("}\n\n\n")
	w.out.WriteString(`def _serve_mod(handlers: Mapping[str, Callable[[Any], Any]], data: bytes) -> bytes:
    """_serve_mod runs the encoded Call in data on handlers and returns the
    encoded Reply. A handler that raises answers with its error and
    traceback."""
    request = wire.decode(_SCHEMA, "Call", data)
    event = _EVENTS.get(request["method"])
    if event is None:
        return wire.encode(_SCHEMA, "Reply", {"error": "the mod has no method " + request["method"]})
    try:
        answer = handlers[event[2]](wire.decode(_SCHEMA, event[0], request["request"]))
        response = wire.encode(_SCHEMA, event[1], answer)
    except Exception:
        return wire.encode(_SCHEMA, "Reply", {"error": traceback.format_exc().rstrip()})
    return wire.encode(_SCHEMA, "Reply", {"response": response})


`)
}

// paramName returns the schema name of a parameter: its field's or oneof's.
func (p *param) paramName() string {
	if p.oneof != nil {
		return p.oneof.name
	}
	return p.field.name
}

// pythonType returns the Python type of a field, repeated or not.
func pythonType(f *field) string {
	if f.repeated {
		return "list[" + pythonBase(f) + "]"
	}
	return pythonBase(f)
}

// pythonBase returns the Python type of one value of a field.
func pythonBase(f *field) string {
	if c := classOf(f); c != nil {
		return c.name
	}
	switch {
	case f.message != nil:
		if name := mapped(f.message); name != "" {
			return name
		}
		return f.message.name
	case f.enum != nil:
		return f.enum.name
	}
	switch f.kind {
	case descriptorpb.FieldDescriptorProto_TYPE_BOOL:
		return "bool"
	case descriptorpb.FieldDescriptorProto_TYPE_STRING:
		return "str"
	case descriptorpb.FieldDescriptorProto_TYPE_BYTES:
		return "bytes"
	case descriptorpb.FieldDescriptorProto_TYPE_DOUBLE, descriptorpb.FieldDescriptorProto_TYPE_FLOAT:
		return "float"
	}
	return "int"
}

// pythonZero returns the zero value of a scalar field.
func pythonZero(f *field) string {
	switch pythonBase(f) {
	case "bool":
		return "False"
	case "str":
		return `""`
	case "bytes":
		return `b""`
	case "float":
		return "0.0"
	}
	return "0"
}

// pythonValue returns the name of an enum value in snake_case:
// SCREEN_EFFECT_MATCH_INTRO becomes match_intro.
func pythonValue(e *enum, v *enumValue) string {
	return strings.ToLower(strings.TrimPrefix(v.name, upperSnake(e.name)+"_"))
}

// snake returns a lowerCamel or UpperCamel name in snake_case.
func snake(name string) string {
	return strings.ToLower(upperSnake(camel(name)))
}

// pythonKeywords are the reserved words of Python, which a name cannot use.
var pythonKeywords = set(strings.Fields(`False None True and as assert async await break class
	continue def del elif else except finally for from global if import in is lambda nonlocal
	not or pass raise return try while with yield`))

// pythonName returns name as a Python identifier, with an underscore after a
// reserved word.
func pythonName(name string) string {
	if pythonKeywords[name] {
		return name + "_"
	}
	return name
}

// pythonFieldDoc returns doc with the UpperCamel names of m's fields in
// snake_case.
func pythonFieldDoc(m *message, doc string) string {
	for _, f := range m.fields {
		doc = regexp.MustCompile(`\b`+camel(f.name)+`\b`).ReplaceAllString(doc, f.name)
	}
	return doc
}

// writePythonDocstring writes text as a docstring at indent.
func writePythonDocstring(out *bytes.Buffer, indent, text string) {
	if text == "" {
		return
	}
	text = strings.ReplaceAll(strings.ReplaceAll(text, `\`, `\\`), `"""`, `\"\"\"`)
	lines := strings.Split(text, "\n")
	if len(lines) == 1 {
		fmt.Fprintf(out, "%s\"\"\"%s\"\"\"\n", indent, text)
		return
	}
	fmt.Fprintf(out, "%s\"\"\"%s\n", indent, lines[0])
	for _, line := range lines[1:] {
		if line == "" {
			out.WriteString("\n")
			continue
		}
		fmt.Fprintf(out, "%s%s\n", indent, line)
	}
	fmt.Fprintf(out, "%s\"\"\"\n", indent)
}
